#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(try_from = "ReleaseDecisionEntryWire", rename_all = "camelCase", deny_unknown_fields)]
pub struct ReleaseDecisionEntry {
