857	fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
858	    workspace: &Workspace<'_, R, D>,
859	    id: &ReleasePackageId,
860	    package: &callisto_model::Package,
861	    version: &Version,
862	    git_remote: Option<&PreparedGitRemote>,
863	) -> Result<SemanticInputDigest, GraphError> {
864	    let mut transcript = CanonicalTranscript::semantic_input_v1();
865	    transcript.push_str("package.id", &id.to_string());
866	    transcript.push_str("package.version", version.render());
867	    for manifest in &package.manifests {
868	        let path = workspace.root.join(&manifest.path);
869	        let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
870	            path: manifest.path.clone(),
871	            message: error.to_string(),
872	        })?;
873	        transcript.push_str("manifest.path", &manifest.path.display().to_string());
874	        transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
875	        transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
876	        transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
877	    }
878	    transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
879	    transcript.push_str(
880	        "package.tag",
881	        &package
882	            .tag_template
883	            .as_ref()
884	            .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
885	    );
886	    let npm_name = workspace
887	        .identity
888	        .native_name(&package.id, callisto_model::Ecosystem::Npm)
889	        .unwrap_or(package.id.name());
890	    for target in &package.publish_to {
891	        transcript.push_str(
892	            "package.target",
893	            target_fingerprint(workspace, &package.id, npm_name, target)?.as_str(),
894	        );
895	    }
896	    if let Some(remote) = git_remote {
897	        transcript.push_str("package.gitRemote", remote.identity.as_str());
898	    }
899	    Ok(SemanticInputDigest::from_transcript(&transcript))
900	}
