965	fn digest_bytes(tag: &str, bytes: &[u8]) -> SemanticInputDigest {
966	    let mut transcript = CanonicalTranscript::semantic_input_v1();
967	    transcript.push_bytes(tag, bytes);
968	    SemanticInputDigest::from_transcript(&transcript)
969	}
