66	fn warn_if_registry_version_adopted(operation: &ReleaseOperationId) {
67	    let package = match &operation.role {
68	        ReleaseOperationRole::RegistryPublish { .. } => &operation.package,
69	        ReleaseOperationRole::PlatformPublish { platform, .. } => platform.name(),
70	        _ => return,
71	    };
72	    eprintln!(
73	        "warning: {package} {} is already published; skipping",
74	        operation.version
75	    );
76	}
77	
78	/// The single seam through which this executor changes state.
79	fn apply(
80	    state: &mut ReleaseExecutionStateV1,
81	    operation: &ReleaseOperationId,
82	    event: &OperationEvent,
83	) -> Result<(), GraphError> {
84	    state
85	        .apply(operation, event)
86	        .map(|_| ())
87	        .map_err(|source| match source {
88	            ReleaseStateError::EvidenceRejected(source) => GraphError::ReleaseProviderObservation { source },
89	            source => GraphError::ReleaseExecutionState { source },
90	        })
91	}
92	
93	/// Refuses to report success until every operation has an observed terminal
94	/// success state.
95	fn require_terminal_success(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<(), GraphError> {
96	    let count = intent
97	        .operations
98	        .iter()
99	        .filter(|operation| {
100	            !state
101	                .operation_state(operation.id())
102	                .is_some_and(OperationState::is_success)
103	        })
104	        .count();
105	    if count == 0 {
106	        Ok(())
107	    } else {
108	        Err(GraphError::ReleaseIncomplete { count })
109	    }
110	}
111	
112	/// Requires the verification capability whenever `intent` declares compiled
113	/// binary slots. Its private constructor already proved both manifest binding
114	/// and local byte/attestation identity.
115	fn require_verified_artifact_manifest(
116	    intent: &ReleaseIntentV1,
117	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
118	) -> Result<(), GraphError> {
119	    match (intent.artifact_slots.is_empty(), artifacts) {
120	        (true, None) => Ok(()),
121	        (true, Some(artifacts)) if !callisto_model::python_publishes(intent).is_empty() => {
122	            require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest()))
123	        }
124	        (true, Some(_)) => Err(GraphError::ReleaseInvariant {
125	            detail: "verified artifact manifest supplied for a release intent with nothing to seal".to_owned(),
126	        }),
127	        (false, Some(artifacts)) => require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest())),
128	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
129	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
130	        }),
131	    }
132	}
133	
134	/// Validates the serializable manifest independently of local byte and
135	/// attestation verification. Kept as a focused invariant helper for tests;
136	/// production execution requires `VerifiedArtifactManifest` above.
137	fn require_artifact_manifest_matches_intent(
138	    intent: &ReleaseIntentV1,
139	    artifacts: Option<&callisto_model::ArtifactManifestV1>,
140	) -> Result<(), GraphError> {
141	    match (intent.artifact_slots.is_empty(), artifacts) {
142	        (true, None) => Ok(()),
143	        (true, Some(manifest)) | (false, Some(manifest)) => manifest
144	            .validate_for_intent(intent)
145	            .map_err(|source| GraphError::ArtifactManifest { source }),
146	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
147	            requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
148	        }),
149	    }
150	}
151	
152	/// The pending operations whose every transitive prerequisite is exactly
153	/// `Published` or `AlreadySatisfied`, in the intent's canonical order.
154	pub(crate) fn eligible_operations(
155	    intent: &ReleaseIntentV1,
156	    state: &ReleaseExecutionStateV1,
157	) -> Vec<ReleaseOperationId> {
158	    let prerequisites: BTreeMap<_, _> = intent
159	        .operations
160	        .iter()
161	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
162	        .collect();
163	    let mut satisfied = BTreeMap::new();
164	    intent
165	        .operations
166	        .iter()
167	        .filter(|operation| state.operation_state(operation.id()) == Some(OperationState::Pending))
168	        .filter(|operation| {
169	            prerequisites_satisfied_transitively(
170	                operation.id(),
171	                &prerequisites,
172	                state,
173	                &mut BTreeSet::new(),
174	                &mut satisfied,
175	            )
176	        })
177	        .map(|operation| operation.id().clone())
178	        .collect()
179	}
180	
181	/// `satisfied` memoizes each subtree's answer, so the walk is linear in the DAG.
182	fn prerequisites_satisfied_transitively(
183	    id: &ReleaseOperationId,
184	    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
185	    state: &ReleaseExecutionStateV1,
186	    on_path: &mut BTreeSet<ReleaseOperationId>,
187	    satisfied: &mut BTreeMap<ReleaseOperationId, bool>,
188	) -> bool {
189	    if let Some(known) = satisfied.get(id) {
190	        return *known;
191	    }
192	    // The intent is already a proven DAG; the on-path guard fails closed on a cycle anyway.
193	    if !on_path.insert(id.clone()) {
194	        return false;
195	    }
196	    let result = prerequisites.get(id).is_some_and(|direct| {
197	        direct.iter().all(|prerequisite| {
198	            state
199	                .operation_state(prerequisite)
200	                .is_some_and(OperationState::is_success)
201	                && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, on_path, satisfied)
202	        })
203	    });
204	    on_path.remove(id);
205	    satisfied.insert(id.clone(), result);
206	    result
207	}
