1	//! Deterministic, graph-owned release roster decisions.
2	//!
3	//! It records the exact package/version authority that later intent construction consumes, without
4	//! exposing a mutation route.
5	
6	use callisto_model::{
7	    BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
8	    ReleaseInclusionReason, ReleasePackageId, Version,
9	};
10	
11	use crate::error::{
12	    CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
13	    UnsupportedReleaseFeature,
14	};
15	use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};
16	
17	/// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
18	/// against `package`'s name.
19	///
20	/// This is the single derivation of release package identity shared by every
21	/// site that computes or verifies release authority: [`derive_release_decision`],
22	/// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
23	/// Per this module's own established lesson (see the doc comment on
24	/// [`derive_release_commit_decision`]), independently reimplementing this
25	/// mapping at each call site is exactly the kind of duplicated derivation
26	/// that drifts -- so it lives here once instead.
27	pub(crate) fn release_package_ids(
28	    identity: &crate::IdentityIndex,
29	    package: &Package,
30	) -> Result<Vec<ReleasePackageId>, GraphError> {
31	    package
32	        .canonical_manifests()
33	        .map(|manifest| {
34	            let ecosystem = manifest.ecosystem();
35	            // A dual-manifest package's manifests may declare different names.
36	            let name = identity
37	                .native_name(&package.id, ecosystem)
38	                .unwrap_or(package.id.name());
39	            ReleasePackageId::new(ecosystem, name)
40	        })
41	        .collect::<Result<Vec<_>, _>>()
42	        .map_err(GraphError::from)
43	}
44	
45	/// Derives the durable roster from a freshly computed version plan.
46	///
47	/// The caller supplies the plan from the same workspace observation; this
48	/// function never inspects a caller-provided release roster.
49	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
50	    workspace: &Workspace<'_, R, D>,
51	    plan: &VersionPlan,
52	) -> Result<ReleaseDecisionV1, GraphError> {
53	    let mut package_ids = std::collections::BTreeMap::new();
54	    for package in workspace.graph.packages() {
55	        let ids = release_package_ids(&workspace.identity, package)?;
56	        package_ids.insert(package.id.clone(), ids);
57	    }
58	
59	    let mut entries = Vec::new();
60	    for bump in &plan.bumps {
61	        // `plan` is contractually derived from this same workspace
62	        // observation (see doc comment above), so every bump's package must
63	        // already be a key here -- a miss means the plan/workspace pairing
64	        // itself is inconsistent, not a recoverable operator condition.
65	        let ids = package_ids
66	            .get(&bump.package)
67	            .ok_or_else(|| GraphError::ReleaseInvariant {
68	                detail: format!(
69	                    "version plan references package `{}`, which is absent from this workspace observation",
70	                    bump.package.display_name()
71	                ),
72	            })?;
73	        for id in ids {
74	            entries.push(ReleaseDecisionEntry {
75	                package: id.clone(),
76	                target_version: bump.to.clone(),
77	                reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
78	            });
79	        }
80	    }
81	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
82	}
83	
84	/// Derives a durable decision for explicit, exact release identities.
85	///
86	/// A linked group is one release unit: selecting any member includes every
87	/// member of that linked group which the version plan selected. All other
88	/// packages remain outside the authority boundary. The caller must pass
89	/// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
90	/// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
91	/// for release authority.
92	pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
93	    workspace: &Workspace<'_, R, D>,
94	    plan: &VersionPlan,
95	    selections: &[ReleasePackageId],
96	) -> Result<ReleaseDecisionV1, GraphError> {
97	    let complete = derive_release_decision(workspace, plan)?;
98	
99	    let mut seen = std::collections::BTreeSet::new();
100	    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
101	        return Err(GraphError::ReleaseSelectionInvalid {
102	            package: duplicate.clone(),
103	            reason: ReleaseSelectionInvalidReason::Duplicate,
104	        });
105	    }
106	
107	    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
108	    for selection in &selected {
109	        let Some(package) = workspace_package(workspace, selection) else {
110	            return Err(GraphError::UnknownPackage {
111	                id: callisto_model::PackageId::Prefixed {
112	                    ecosystem: selection.ecosystem(),
113	                    name: selection.name().to_string(),
114	                },
115	            });
116	        };
117	        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
118	            ReleaseSelectionInvalidReason::NotARelease
119	        } else if package
120	            .publish_to
121	            .iter()
122	            .all(|target| matches!(target, callisto_model::PublishTarget::None))
123	        {
124	            ReleaseSelectionInvalidReason::NoDispatchableTarget
125	        } else {
126	            continue;
127	        };
128	        return Err(GraphError::ReleaseSelectionInvalid {
129	            package: (*selection).clone(),
130	            reason,
131	        });
132	    }
133	
134	    let entries = expand_selection(workspace, complete.entries, &selected);
135	    ReleaseDecisionV1::new(entries).map_err(GraphError::from)
136	}
137	
138	/// Keeps the selected entries plus every entry sharing a fixed or linked group
139	/// with a selection. Both release routes narrow `--package` through this.
140	fn expand_selection<R: callisto_model::CommandRunner, D: DependencyResolver>(
141	    workspace: &Workspace<'_, R, D>,
142	    entries: Vec<ReleaseDecisionEntry>,
143	    selected: &std::collections::BTreeSet<&ReleasePackageId>,
144	) -> Vec<ReleaseDecisionEntry> {
145	    // A plan-derived entry carries its linked group as a reason.
146	    let reason_groups = entries
147	        .iter()
148	        .filter(|entry| selected.contains(&entry.package))
149	        .flat_map(|entry| entry.reasons.iter())
150	        .filter_map(|reason| match reason {
151	            ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
152	            _ => None,
153	        })
154	        .collect::<std::collections::BTreeSet<_>>();
155	    // Config membership: a selected member's own reason is often `Changeset` or `UnreleasedVersion`.
156	    let config_groups = selected
157	        .iter()
158	        .flat_map(|selection| release_groups_of(workspace, selection))
159	        .collect::<std::collections::BTreeSet<_>>();
160	    entries
161	        .into_iter()
162	        .filter(|entry| {
163	            selected.contains(&entry.package)
164	                || entry.reasons.iter().any(|reason| {
165	                    matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if reason_groups.contains(group_id))
166	                })
167	                || release_groups_of(workspace, &entry.package)
168	                    .iter()
169	                    .any(|group| config_groups.contains(group))
170	        })
171	        .collect()
172	}
173	
174	/// Derives the roster of every publishable package whose current version has
175	/// no tag in the canonical [`crate::TagIndex`], each with
176	/// [`ReleaseInclusionReason::UnreleasedVersion`].
177	///
178	/// A non-empty `selections` restricts the roster to exactly those identities,
179	/// each of which must be unreleased and publishable. `None` means nothing is
180	/// unreleased.
181	pub fn derive_unreleased_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
182	    workspace: &Workspace<'_, R, D>,
183	    selections: &[ReleasePackageId],
184	) -> Result<Option<ReleaseDecisionV1>, GraphError> {
185	    derive_release_roster(workspace, selections, &std::collections::BTreeSet::new())
186	}
187	
188	/// [`derive_unreleased_decision`] that also keeps the tagged releases in `resumable`: a tag
189	/// does not prove the rest of the release was observed.
190	pub(crate) fn derive_release_roster<R: callisto_model::CommandRunner, D: DependencyResolver>(
191	    workspace: &Workspace<'_, R, D>,
192	    selections: &[ReleasePackageId],
193	    resumable: &std::collections::BTreeSet<ReleasePackageId>,
194	) -> Result<Option<ReleaseDecisionV1>, GraphError> {
195	    let versions = workspace.base_versions()?;
196	    let tags = workspace.tags()?;
197	    let mut entries = Vec::new();
198	    for package in workspace.graph.packages() {
199	        if !has_dispatchable_target(package) {
200	            continue;
201	        }
202	        let version = versions.get(&package.id).ok_or_else(|| GraphError::ReleaseInvariant {
203	            detail: format!("package `{}` has no base version", package.id.display_name()),
204	        })?;
205	        let ids = release_package_ids(&workspace.identity, package)?;
206	        if version_is_tagged(tags, &package.id, version) && !ids.iter().any(|id| resumable.contains(id)) {
207	            continue;
208	        }
209	        for id in ids {
210	            entries.push(ReleaseDecisionEntry {
211	                package: id,
212	                target_version: version.clone(),
213	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
214	            });
215	        }
216	    }
217	
218	    let mut seen = std::collections::BTreeSet::new();
219	    for selection in selections {
220	        if !seen.insert(selection) {
221	            return Err(GraphError::ReleaseSelectionInvalid {
222	                package: selection.clone(),
223	                reason: ReleaseSelectionInvalidReason::Duplicate,
224	            });
225	        }
226	        let Some(package) = workspace_package(workspace, selection) else {
227	            return Err(GraphError::UnknownPackage {
228	                id: callisto_model::PackageId::Prefixed {
229	                    ecosystem: selection.ecosystem(),
230	                    name: selection.name().to_string(),
231	                },
232	            });
233	        };
234	        if !has_dispatchable_target(package) {
235	            return Err(GraphError::ReleaseSelectionInvalid {
236	                package: selection.clone(),
237	                reason: ReleaseSelectionInvalidReason::NoDispatchableTarget,
238	            });
239	        }
240	        if !entries.iter().any(|entry| &entry.package == selection) {
241	            return Err(GraphError::ReleaseSelectionInvalid {
242	                package: selection.clone(),
243	                reason: ReleaseSelectionInvalidReason::NotARelease,
244	            });
245	        }
246	    }
247	    if !selections.is_empty() {
248	        entries = expand_selection(workspace, entries, &seen);
249	    }
250	    if entries.is_empty() {
251	        return Ok(None);
252	    }
253	    ReleaseDecisionV1::new(entries).map(Some).map_err(GraphError::from)
254	}
255	
256	/// Whether `version` of `package` already has a tag in the canonical [`crate::TagIndex`].
257	pub(crate) fn version_is_tagged(
258	    tags: &crate::TagIndex,
259	    package: &callisto_model::PackageId,
260	    version: &Version,
261	) -> bool {
262	    tag_of_version(tags, package, version).is_some()
263	}
264	
265	fn tag_of_version(tags: &crate::TagIndex, package: &callisto_model::PackageId, version: &Version) -> Option<String> {
266	    let rendered = tags.template(package).render(version).to_string();
267	    if tags.contains_tag(&rendered) {
268	        return Some(rendered);
269	    }
270	    tags.last_tag(package)
271	        .filter(|tag| &tag.version == version)
272	        .map(|tag| tag.name.to_string())
273	}
274	
275	/// Entries for every publishable package whose current version is tagged on `source`.
276	///
277	/// A run that created such a tag may have stopped before pushing it or finishing the release.
278	pub(crate) fn releases_tagged_at<R: callisto_model::CommandRunner, D: DependencyResolver>(
279	    workspace: &Workspace<'_, R, D>,
280	    source: &CommitSha,
281	) -> Result<Vec<ReleaseDecisionEntry>, GraphError> {
282	    let versions = workspace.base_versions()?;
283	    let tags = workspace.tags()?;
284	    let git = workspace.git_access();
285	    let mut entries = Vec::new();
286	    for package in workspace.graph.packages() {
287	        if !has_dispatchable_target(package) {
288	            continue;
289	        }
290	        let Some(version) = versions.get(&package.id) else {
291	            continue;
292	        };
293	        // Only the tag this run's tag operation would create: one made under an older template is another release's.
294	        let tag = tags.template(&package.id).render(version).to_string();
295	        if !tags.contains_tag(&tag) {
296	            continue;
297	        }
298	        if git.resolve_commit(&tag)?.as_ref() != Some(source) {
299	            continue;
300	        }
301	        for id in release_package_ids(&workspace.identity, package)? {
302	            entries.push(ReleaseDecisionEntry {
303	                package: id,
304	                target_version: version.clone(),
305	                reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
306	            });
307	        }
308	    }
309	    Ok(entries)
310	}
311	
312	pub(crate) fn has_dispatchable_target(package: &Package) -> bool {
313	    package
314	        .publish_to
315	        .iter()
316	        .any(|target| !matches!(target, callisto_model::PublishTarget::None))
317	}
318	
319	/// The workspace package with this exact release identity.
320	fn workspace_package<'w, R: callisto_model::CommandRunner, D: DependencyResolver>(
321	    workspace: &'w Workspace<'_, R, D>,
322	    id: &ReleasePackageId,
323	) -> Option<&'w Package> {
324	    // By release identity, not name: a dual-manifest package's npm name can differ from its id.
325	    workspace
326	        .graph
327	        .packages()
328	        .find(|package| release_package_ids(&workspace.identity, package).is_ok_and(|ids| ids.contains(id)))
329	}
330	
331	/// The fixed and linked groups a release package belongs to, per config.
332	fn release_groups_of<R: callisto_model::CommandRunner, D: DependencyResolver>(
333	    workspace: &Workspace<'_, R, D>,
334	    id: &ReleasePackageId,
335	) -> Vec<(&'static str, callisto_model::GroupName)> {
336	    let Some(package) = workspace_package(workspace, id) else {
337	        return Vec::new();
338	    };
339	    let groups = &workspace.config.groups;
340	    let fixed = groups.fixed_of.iter().map(|(member, group)| ("fixed", member, group));
341	    let linked = groups.linked_of.iter().map(|(member, group)| ("linked", member, group));
342	    // `member` keys are already canonical (`GroupTable::resolve` resolved
343	    // them through `IdentityIndex::resolve`), so exact equality is correct
344	    // here -- `PackageId::matches` would treat a Bare member key as an
345	    // ecosystem wildcard and could match a same-named package elsewhere.
346	    fixed
347	        .chain(linked)
348	        .filter(|(_, member, _)| **member == package.id)
349	        .map(|(kind, _, group)| (kind, group.clone()))
350	        .collect()
351	}
352	
353	/// Verifies the release roster a merged release commit claims, against a
354	/// release-decision file committed alongside it at `decision_path`.
355	///
356	/// This is intentionally *not* a second computation of changeset, fixed-group,
357	/// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
358	/// (via [`derive_release_decision`]) already computed that once, correctly,
359	/// when the release PR was generated -- and `callisto version --emit-decision`
360	/// commits its exact output alongside the manifest and changelog edits.
361	/// Re-deriving that policy a second time here, from raw git diffs, is exactly
362	/// the kind of duplicated logic that drifts: an earlier version of this
363	/// function did just that, understood only a direct changeset match, and
364	/// rejected every real release in this repository once a fixed-group cascade
365	/// (a case its reimplementation never learned) touched an unnamed sibling.
366	///
367	/// Instead, this function reads the committed decision back and confirms the
368	/// commit's actual diff matches it exactly -- no more, no less.
369	/// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
370	/// entries don't match its content digest, so a hand-edited or corrupted
371	/// decision file fails before this function's own diff cross-check runs.
372	///
373	/// The caller must check out the exact merge commit in detached HEAD state
374	/// before creating an intent. GitHub-specific PR/approval provenance belongs
375	/// in the workflow boundary; this graph function verifies the local,
376	/// provider-neutral commit delta only.
377	pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
378	    workspace: &Workspace<'_, R, D>,
379	    release_commit: &CommitSha,
380	    decision_path: &std::path::Path,
381	) -> Result<ReleaseDecisionV1, GraphError> {
382	    let head_args = ["rev-parse", "HEAD"];
383	    let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
384	    let head =
385	        CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
386	    if &head != release_commit {
387	        return Err(GraphError::ReleaseCommitVerificationFailed {
388	            commit: release_commit.clone(),
389	            reason: CommitVerificationFailure::HeadMismatch,
390	        });
391	    }
392	
393	    let parent_ref = format!("{}^", release_commit.as_str());
394	    let parent_args = ["rev-parse", parent_ref.as_str()];
395	    let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
396	    CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
397	
398	    let diff_tree_args = [
399	        "diff-tree",
400	        "--no-commit-id",
401	        "--name-status",
402	        "-r",
403	        "--no-renames",
404	        parent.as_str(),
405	        release_commit.as_str(),
406	    ];
407	    let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
408	    let changed = parse_name_status(&changed, &diff_tree_args)?;
409	
410	    // The decision must be freshly authored as part of *this* commit, not a
411	    // stale leftover an earlier release already committed and this one never
412	    // touched -- otherwise a commit that changes nothing real could still
413	    // carry forward a prior, unrelated decision's authority.
414	    let decision_path_str = normalized_git_path(decision_path)?;
415	    let decision_freshly_written = changed
416	        .iter()
417	        .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
418	    if !decision_freshly_written {
419	        return Err(GraphError::ReleaseCommitVerificationFailed {
420	            commit: release_commit.clone(),
421	            reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
422	        });
423	    }
424	
425	    // A cheap, independent sanity check that this commit is a real version
426	    // application and not just a hand-crafted decision file: some real
427	    // changeset was actually consumed. The decision's own entries, not this
428	    // changeset's content, remain the sole authority verified below.
429	    let changeset_dir = normalized_git_path(&workspace.config.changesets_dir)?;
430	    let consumed_a_changeset = changed
431	        .iter()
432	        .any(|(status, path)| status == "D" && is_changeset_path(path, &changeset_dir));
433	    if !consumed_a_changeset {
434	        return Err(GraphError::ReleaseCommitVerificationFailed {
435	            commit: release_commit.clone(),
436	            reason: CommitVerificationFailure::NoChangesetConsumed,
437	        });
438	    }
439	
440	    let decision_source = git_file(
441	        workspace.runner,
442	        &workspace.root,
443	        release_commit.as_str(),
444	        &decision_path_str,
445	    )?;
446	    let decision: ReleaseDecisionV1 =
447	        serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
448	            path: decision_path.to_path_buf(),
449	            message: error.to_string(),
450	        })?;
451	    let claimed = decision
452	        .entries
453	        .iter()
454	        .map(|entry| (entry.package.clone(), entry.target_version.clone()))
455	        .collect::<std::collections::BTreeMap<_, _>>();
456	
457	    let changed_paths = changed
458	        .iter()
459	        .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
460	        .collect::<std::collections::BTreeSet<_>>();
461	
462	    // Every canonical manifest path this workspace currently declares, in
463	    // the exact order `workspace.graph.packages()` and
464	    // `Package::canonical_manifests()` yield -- both are backed by ordered
465	    // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
466	    // the second traversal below visits the same (package, manifest) pairs
467	    // in the same order. That lets it zip the batched `before`/`after`
468	    // results back on by position instead of re-keying by path, which would
469	    // misbehave if two packages ever declared an identical manifest path.
470	    let manifest_queries: Vec<(String, Ecosystem)> = workspace
471	        .graph
472	        .packages()
473	        .flat_map(Package::canonical_manifests)
474	        .map(|manifest| Ok((normalized_git_path(&manifest.path)?, manifest.ecosystem())))
475	        .collect::<Result<_, GraphError>>()?;
476	    // Each Cargo manifest may inherit its version from a workspace manifest above it, so those are fetched too.
477	    let mut query_path_list: Vec<String> = manifest_queries.iter().map(|(path, _)| path.clone()).collect();
478	    for (path, _) in manifest_queries
479	        .iter()
480	        .filter(|(_, ecosystem)| *ecosystem == Ecosystem::Cargo)
481	    {
482	        for candidate in callisto_manifests::workspace_manifest_candidates(&workspace.root, std::path::Path::new(path))?
483	        {
484	            let candidate = normalized_git_path(&candidate)?;
485	            if !query_path_list.contains(&candidate) {
486	                query_path_list.push(candidate);
487	            }
488	        }
489	    }
490	    let query_paths: Vec<&str> = query_path_list.iter().map(String::as_str).collect();
491	
492	    // Exactly two `git cat-file --batch` subprocess invocations total (one
493	    // per commit), regardless of how many canonical manifests the
494	    // workspace has -- replaces what was previously 2*N separate `git
495	    // show` spawns (one `manifest_version_at` call per manifest per
496	    // commit).
497	    let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
498	    let after_blobs =
499	        batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
500	    let before = CommitBlobs::new(workspace.runner, &workspace.root, &parent, &query_paths, before_blobs);
501	    let after = CommitBlobs::new(
502	        workspace.runner,
503	        &workspace.root,
504	        release_commit.as_str(),
505	        &query_paths,
506	        after_blobs,
507	    );
508	    let before_versions = resolve_batch_versions(&before, &manifest_queries)?;
509	    let after_versions = resolve_batch_versions(&after, &manifest_queries)?;
510	
511	    let mut observed = std::collections::BTreeSet::new();
512	    let mut manifest_index = 0usize;
513	    for package in workspace.graph.packages() {
514	        let package_ids = release_package_ids(&workspace.identity, package)?;
515	        let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
516	        if package_is_claimed {
517	            let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
518	                requirement: ReleasePreconditionRequirement::ChangelogConfigured,
519	            })?;
520	            let changelog = normalized_git_path(changelog)?;
521	            if !changed_paths.contains(changelog.as_str()) {
522	                return Err(GraphError::ReleaseCommitVerificationFailed {
523	                    commit: release_commit.clone(),
524	                    reason: CommitVerificationFailure::ChangelogNotTouched,
525	                });
526	            }
527	        }
528	        for id in package_ids {
529	            let before = &before_versions[manifest_index];
530	            let after = &after_versions[manifest_index];
531	            manifest_index += 1;
532	            let changed_version = before.version != after.version;
533	            match claimed.get(&id) {
534	                Some(target_version) => {
535	                    if !changed_paths.contains(after.authority.to_string_lossy().as_ref()) {
536	                        return Err(GraphError::ReleaseCommitVerificationFailed {
537	                            commit: release_commit.clone(),
538	                            reason: CommitVerificationFailure::ManifestNotInDiff,
539	                        });
540	                    }
541	                    if !changed_version || &after.version != target_version {
542	                        return Err(GraphError::ReleaseCommitVerificationFailed {
543	                            commit: release_commit.clone(),
544	                            reason: CommitVerificationFailure::ManifestVersionMismatch,
545	                        });
546	                    }
547	                    observed.insert(id);
548	                }
549	                None => {
550	                    if changed_version {
551	                        // A changed version the committed decision never
552	                        // claimed is not this commit's authority -- fail
553	                        // closed rather than trust a partial match.
554	                        return Err(GraphError::ReleaseCommitVerificationFailed {
555	                            commit: release_commit.clone(),
556	                            reason: CommitVerificationFailure::UnclaimedVersionChange,
557	                        });
558	                    }
559	                }
560	            }
561	        }
562	    }
563	    if observed.len() != claimed.len() {
564	        return Err(GraphError::ReleaseCommitVerificationFailed {
565	            commit: release_commit.clone(),
566	            reason: CommitVerificationFailure::ClaimedPackageNotObserved,
567	        });
568	    }
569	
570	    Ok(decision)
571	}
572	
573	fn is_changeset_path(path: &str, changeset_dir: &str) -> bool {
574	    let Some(file_name) = path.strip_prefix(changeset_dir).and_then(|path| {
575	        if changeset_dir.is_empty() {
576	            Some(path)
577	        } else {
578	            path.strip_prefix('/')
579	        }
580	    }) else {
581	        return false;
582	    };
583	
584	    !file_name.contains('/') && file_name.ends_with(".md") && file_name != "README.md"
585	}
586	
587	/// Builds a [`GraphError::ReleaseCommand`] (E164) for a git invocation that
588	/// exited non-zero, carrying its real exit status and stderr instead of
589	/// discarding them.
590	fn command_non_zero_exit(program: &str, args: &[&str], output: &callisto_model::CommandOutput) -> GraphError {
591	    GraphError::ReleaseCommand {
592	        program: program.to_string(),
593	        args: args.iter().map(|s| s.to_string()).collect(),
594	        failure: CommandFailure::NonZeroExit {
595	            exit_code: output.exit_code,
596	            stderr: output.stderr.clone(),
597	        },
598	    }
599	}
