62	    fn publish(
63	        &self,
64	        context: &ProviderContext<'_>,
65	        request: &ProviderRequest<'_>,
66	        _effect: &EffectAuthorization<'_>,
67	    ) -> Result<ExactEvidence, GraphError> {
68	        let operation = registry_operation(request)?;
69	        let adapter = adapter_for(request.id.package.ecosystem())?;
70	        let output = adapter.publish(context, request.id, operation, request.artifacts)?;
71	        let outcome = adapter.classify(&output).map_err(|source| GraphError::Registry {
72	            package: operation.package_name.clone(),
73	            source,
74	        })?;
75	        // Neither a zero exit nor the client's "already exists" text is a
76	        // receipt: a yanked version is not the version this intent authorized,
77	        // so only an exact observation may satisfy the operation.
78	        let confirmed = adapter.confirm(
79	            context,
80	            request.id,
81	            operation,
82	            matches!(outcome, PublishOutcome::Published),
83	            request.artifacts,
84	        )?;
85	        require_registry_confirmation(
86	            confirmed.is_terminal_success(),
87	            &operation.package_name,
88	            &operation.version,
89	        )?;
90	        confirmed
91	            .exact_evidence()
92	            .ok_or_else(|| GraphError::RegistryPublishUnconfirmed {
93	                package: operation.package_name.clone(),
94	                version: operation.version.clone(),
95	            })
96	    }
97	}
