148	/// One ecosystem's registry client. This is the single place the release path
149	/// branches on [`Ecosystem`]: adding a registry means adding an adapter here,
150	/// not another match in preflight, dispatch, or confirmation.
151	pub(crate) trait RegistryEcosystem {
152	    /// Whether this registry exposes a query that proves an exact published
153	    /// version. `false` makes every observation `Indeterminate`, so a publish
154	    /// is never confirmed here and instead fails closed at the mandatory
155	    /// post-effect exact observation.
156	    fn can_observe_versions(&self) -> bool;
157	
158	    /// One observation attempt. Only called when [`Self::can_observe_versions`].
159	    fn observe_once(
160	        &self,
161	        context: &ProviderContext<'_>,
162	        operation: &RegistryPublishOperation,
163	    ) -> Result<Attempt<ProviderObservationV1>, GraphError>;
164	
165	    /// Runs the publish client and returns the output that decides the outcome.
166	    fn publish(
167	        &self,
168	        context: &ProviderContext<'_>,
169	        id: &ReleaseOperationId,
170	        operation: &RegistryPublishOperation,
171	        artifacts: Option<&VerifiedArtifactManifest<'_>>,
172	    ) -> Result<CommandOutput, GraphError>;
173	
174	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError>;
175	
176	    /// What the one fresh pre-effect observation authorizes.
177	    fn preflight(
178	        &self,
179	        context: &ProviderContext<'_>,
180	        id: &ReleaseOperationId,
181	        operation: &RegistryPublishOperation,
182	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
183	    ) -> Result<ReleasePreflight, GraphError> {
184	        match registry_observation(self, context, operation)? {
185	            // A registry with no query API at all has nothing to observe
186	            // before the effect; the post-effect confirmation fails closed.
187	            ProviderObservationV1::Indeterminate {
188	                cause: ProviderIndeterminateCause::UnsupportedProvider,
189	            } => Ok(proceed()),
190	            observation => preflight_from_observation(observation, id, RemoteConflict::RegistryVersionDiffers),
191	        }
192	    }
193	
194	    /// The observation that lets a finished publish be recorded; `published` means the index may still lag.
195	    fn confirm(
196	        &self,
197	        context: &ProviderContext<'_>,
198	        _id: &ReleaseOperationId,
199	        operation: &RegistryPublishOperation,
200	        published: bool,
201	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
202	    ) -> Result<ProviderObservationV1, GraphError> {
203	        if published && self.can_observe_versions() {
204	            confirmed_registry_observation(self, context, operation)
205	        } else {
206	            registry_observation(self, context, operation)
207	        }
208	    }
209	}
