346	/// The observation argv: `cargo info NAME@VERSION --registry REGISTRY`.
347	///
348	/// `--registry` is never omitted. Without it `cargo info` resolves the local
349	/// workspace and reports an unpublished member's on-disk version as published
350	/// (`version: X (from ./)`), which is the defect this observation exists to
351	/// avoid; with it, cargo reads only the named registry.
352	///
353	/// `net.retry=0` must precede `info` (cargo ignores it after the subcommand):
354	/// callisto's bounded retry owns retrying, and cargo's own backoff inside each
355	/// attempt made an unreachable registry take ~11s per attempt.
356	fn cargo_info_args<'a>(spec: &'a str, registry: &'a str) -> [&'a str; 6] {
357	    ["--config", "net.retry=0", "info", spec, "--registry", registry]
358	}
