415	/// Classifies one real `cargo info` run. There is no `--json`, so the two
416	/// answers cargo actually proves are read from its exit code and its text:
417	///
418	/// - exit 0 with a `version: VERSION` line for the requested version: `Exact`.
419	///   `cargo info` reports neither the index checksum nor the yank flag, so the
420	///   evidence says `None` for both rather than inventing them.
421	/// - exit 101 with ``could not find `NAME@VERSION` ``: `Absent`.
422	/// - anything else -- another exit code, another message (a network failure
423	///   prints ``failed to load source for dependency``), or a zero exit with no
424	///   matching version line: transient `Indeterminate`, retried by the bounded
425	///   policy. An unreachable registry must never read as an absence.
426	///
427	/// A *yanked* version reads as `Absent`, because `cargo info` cannot see yanks
428	/// and answers "could not find" for one. That fails closed rather than open:
429	/// the publish attempt that follows is refused by the registry, and since only
430	/// an `Exact` observation may satisfy an operation, the run ends in the typed
431	/// `RegistryPublishUnconfirmed` error instead of a receipt.
432	fn classify_cargo_info(output: &CommandOutput, spec: &str, version: &Version) -> Attempt<ProviderObservationV1> {
433	    if output.success() {
434	        return if reports_version(&output.stdout, version) {
435	            settled(ProviderObservationV1::Exact {
436	                evidence: ProviderEvidenceV1::RegistryVersion {
437	                    version: version.clone(),
438	                    checksum: None,
439	                    yanked: None,
440	                },
441	            })
442	        } else {
443	            transient(ProviderIndeterminateCause::MalformedResponse, None)
444	        };
445	    }
446	    if output.exit_code == Some(101) && output.stderr.contains(&format!("could not find `{spec}`")) {
447	        return settled(ProviderObservationV1::Absent);
448	    }
449	    transient(ProviderIndeterminateCause::CommandFailed, None)
450	}
451	
452	/// Whether cargo's `version: X ...` line names exactly the requested version.
453	fn reports_version(stdout: &str, version: &Version) -> bool {
454	    stdout.lines().any(|line| {
455	        line.trim()
456	            .strip_prefix("version: ")
457	            .and_then(|rest| rest.strip_prefix(version.render()))
458	            .is_some_and(|rest| rest.is_empty() || rest.starts_with(char::is_whitespace))
459	    })
460	}
461	
462	/// The code npm gives a registry 404 for a package or a version.
463	const NPM_NOT_FOUND_CODE: &str = "E404";
464	
465	/// Only npm's own `E404` code proves absence, never text around it; any other failure is a retried `CommandFailed`.
466	fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
467	    if output.success() {
468	        return if output.stdout_trimmed().is_empty() {
469	            transient(ProviderIndeterminateCause::MalformedResponse, None)
470	        } else {
471	            settled(ProviderObservationV1::Exact {
472	                evidence: ProviderEvidenceV1::RegistryVersion {
473	                    version: version.clone(),
474	                    checksum: None,
475	                    yanked: None,
476	                },
477	            })
478	        };
479	    }
480	    let code = if output.stdout_trimmed().is_empty() {
481	        npm_stderr_code(&output.stderr)
482	    } else {
483	        npm_error_code(&output.stdout)
484	    };
485	    if code.as_deref() == Some(NPM_NOT_FOUND_CODE) {
486	        return settled(ProviderObservationV1::Absent);
487	    }
488	    transient(ProviderIndeterminateCause::CommandFailed, None)
489	}
490	
491	/// The `error.code` of the JSON error body `npm --json` prints to stdout on failure.
492	fn npm_error_code(stdout: &str) -> Option<String> {
493	    let body: serde_json::Value = serde_json::from_str(stdout.trim()).ok()?;
494	    body.get("error")?.get("code")?.as_str().map(str::to_owned)
495	}
496	
497	/// The code on npm's `npm ERR! code X` or `npm error code X` stderr line; npm 8 prints no JSON body.
498	fn npm_stderr_code(stderr: &str) -> Option<String> {
499	    stderr.lines().find_map(|line| {
500	        let rest = line
501	            .strip_prefix("npm ERR! ")
502	            .or_else(|| line.strip_prefix("npm error "))?;
503	        rest.strip_prefix("code ").map(|code| code.trim().to_owned())
504	    })
505	}
