509	impl RegistryEcosystem for NpmRegistry {
510	    fn can_observe_versions(&self) -> bool {
511	        true
512	    }
513	
514	    /// `npm view` never reads the local package; its cwd is only where the project `.npmrc` supplying the registry is
515	    /// read from. That must be where publishing runs, or the two could address different registries, so it is the
516	    /// workspace that owns the package.
517	    fn observe_once(
518	        &self,
519	        context: &ProviderContext<'_>,
520	        operation: &RegistryPublishOperation,
521	    ) -> Result<Attempt<ProviderObservationV1>, GraphError> {
522	        let spec = format!("{}@{}", operation.package_name, operation.version.render());
523	        // Callisto's bounded retry owns retrying; npm's own fetch retries made an
524	        // unreachable registry take ~70s per attempt.
525	        let mut args = vec!["view", spec.as_str(), "--json", "--fetch-retries=0"];
526	        if let Some(registry) = operation.registry.endpoint.as_deref() {
527	            args.extend(["--registry", registry]);
528	        }
529	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
530	        let output = match run_observation(
531	            context.runner(),
532	            programs::NPM,
533	            &args,
534	            &context.root().join(workspace_dir),
535	            timeouts::REGISTRY_QUERY,
536	            true,
537	        )? {
538	            Ok(output) => output,
539	            Err(_unavailable) => return Ok(transient(ProviderIndeterminateCause::CommandFailed, None)),
540	        };
541	        Ok(classify_npm_view(&output, &operation.version))
542	    }
543	
544	    fn publish(
545	        &self,
546	        context: &ProviderContext<'_>,
547	        _id: &ReleaseOperationId,
548	        operation: &RegistryPublishOperation,
549	        _artifacts: Option<&VerifiedArtifactManifest<'_>>,
550	    ) -> Result<CommandOutput, GraphError> {
551	        let workspace_dir = crate::workspace_owner::npm_workspace_dir(context.root(), &operation.package_dir)?;
552	        if operation.by_directory {
553	            let argv = registry_argv::npm_publish_directory_argv(
554	                context.root(),
555	                &workspace_dir,
556	                &operation.package_dir,
557	                &operation.package_name,
558	                operation.npm_tag.as_deref(),
559	                operation.npm_access,
560	                operation.registry.endpoint.as_deref(),
561	            );
562	            return run_npm_publish_argv(context, &argv);
563	        }
564	        // The package manager and the directory it runs in belong to the workspace that holds the package.
565	        let workspace_root = context.root().join(&workspace_dir);
566	        let package_manager = registry_argv::detect_npm_package_manager(&workspace_root)?;
567	        let within_workspace = operation
568	            .package_dir
569	            .strip_prefix(&workspace_dir)
570	            .unwrap_or(&operation.package_dir);
571	        let argv = registry_argv::npm_publish_argv(
572	            &workspace_root,
573	            within_workspace,
574	            &operation.package_name,
575	            package_manager,
576	            operation.npm_tag.as_deref(),
577	            operation.npm_access,
578	            operation.registry.endpoint.as_deref(),
579	        );
580	        run_npm_publish_argv(context, &argv)
581	    }
582	
583	    fn classify(&self, output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
584	        registry_argv::classify_npm_publish_output(output)
585	    }
586	}
