592	/// missing project both look like "no versions found" to it. The index itself
593	/// answers plainly -- 200 with a `files[]` entry naming the version, or 404 --
594	/// so observation goes straight to `https://pypi.org/simple/<project>/`
595	/// (or the configured private index) over `curl`, never through `pip`.
596	const PYPI_DEFAULT_SIMPLE_INDEX: &str = "https://pypi.org/simple";
597	
598	/// PEP 691: the versioned JSON media type, so the index cannot fall back to
599	/// the legacy HTML page a bare GET would otherwise serve.
600	const PYPI_SIMPLE_ACCEPT: &str = "application/vnd.pypi.simple.v1+json";
601	
602	/// The project's simple-index URL: the configured private index if one is
603	/// bound (already https-validated in `binding.rs`), else the public default.
604	fn pypi_simple_index_url(endpoint: Option<&str>, package_name: &str) -> String {
605	    let base = endpoint.unwrap_or(PYPI_DEFAULT_SIMPLE_INDEX);
606	    let project = normalize_pypi_project_name(package_name);
607	    format!("{}/{project}/", base.trim_end_matches('/'))
