609	
610	/// The version segment of a simple-index filename, or `None` for an extension
611	/// this parser does not recognize (a legacy installer, say).
612	fn pypi_simple_file_version(filename: &str) -> Option<&str> {
613	    callisto_model::pypi_dist_filename_parts(filename).map(|(_, version)| version)
614	}
615	
616	/// Whether a simple-index file's filename names exactly the requested version.
617	fn pypi_simple_file_matches(file: &PypiSimpleFile, version: &Version) -> bool {
618	    pypi_simple_file_version(&file.filename).is_some_and(|candidate| {
