245	fn render_release_plan_table(intent: &ReleaseIntentV1) -> String {
246	    use comfy_table::{presets::UTF8_FULL, Cell, Color, Table};
247	
248	    let mut table = Table::new();
249	    // Our `use_color` gate is the sole authority -- never let comfy-table's own
250	    // TTY probe override it, so a forced/piped stdout still renders styled.
251	    table.force_no_tty().enforce_styling();
252	    table.load_preset(UTF8_FULL);
253	    table.set_header(vec!["Package", "Version", "Operations"]);
254	    for entry in &intent.decision.entries {
255	        let steps: Vec<String> = intent
256	            .operations
257	            .iter()
258	            .filter(|op| op.id().package == entry.package)
259	            .map(describe_operation)
260	            .collect();
261	        table.add_row(vec![
262	            Cell::new(entry.package.to_string()),
263	            Cell::new(entry.target_version.to_string()).fg(Color::Green),
264	            Cell::new(steps.join("\n")),
265	        ]);
266	    }
267	    format!("{table}\n")
268	}
