390	fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
391	    if global.dry_run {
392	        return Err(CliError::ReleasePlanDryRun);
393	    }
394	    let runner = CliCommandRunner;
395	    let source_global = source_global(global, args.source_root.as_deref());
396	    let workspace = load_workspace(&source_global, &runner)?;
397	    let decision = match args.from_release_commit.as_deref() {
398	        Some(raw) => {
399	            let commit = callisto_model::CommitSha::parse(raw).map_err(|error| CliError::ReleaseCommitInvalid {
400	                raw: raw.to_owned(),
401	                detail: error.to_string(),
402	            })?;
403	            let decision_path = args
404	                .decision
405	                .as_deref()
406	                .expect("clap requires --decision alongside --from-release-commit");
407	            // The workflow intentionally passes an absolute decision path
408	            // from its separately checked-out release source. Git's commit
409	            // diff and `git show REV:path` both require a repository-relative
410	            // path, so normalize once at the CLI boundary rather than asking
411	            // graph code to infer a caller's checkout layout.
412	            let decision_path = if decision_path.is_absolute() {
413	                let decision_path = dunce::canonicalize(decision_path).map_err(|source| CliError::Io {
414	                    source,
415	                    path: Some(decision_path.to_path_buf()),
416	                })?;
417	                decision_path
418	                    .strip_prefix(&workspace.root)
419	                    .map_err(|_outside_source| CliError::ReleaseDecisionOutsideSource {
420	                        decision: decision_path.display().to_string(),
421	                        root: workspace.root.display().to_string(),
422	                    })?
423	                    .to_path_buf()
424	            } else {
425	                decision_path.to_path_buf()
426	            };
427	            let decision_path = callisto_model::workspace_relative(&decision_path).map_err(|error| {
428	                CliError::ReleaseDecisionPathInvalid {
429	                    path: decision_path.display().to_string(),
430	                    detail: error.to_string(),
431	                }
432	            })?;
433	            derive_release_commit_decision(&workspace, &commit, &decision_path)?
434	        }
435	        None => {
436	            let selections = parse_selections(&args.packages)?;
437	            let inference = select_inference();
438	            let version_plan =
439	                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
440	            derive_selected_release_decision(&workspace, &version_plan, &selections)?
441	        }
442	    };
443	    let locator = IgnoreWalkLocator::new(&workspace.root);
444	    let (intent, diagnostics) = match (
445	        &workspace.config.product_release,
446	        &args.orchestration_revision,
447	        &args.artifact_repository,
448	    ) {
449	        (Some(_), Some(revision), Some(repository)) => {
450	            let workflow_commit = callisto_model::CommitSha::parse(revision).map_err(|error| {
451	                CliError::ReleaseOrchestrationRevisionInvalid {
452	                    revision: revision.clone(),
453	                    detail: error.to_string(),
454	                }
455	            })?;
456	            let repository = callisto_model::GitHubRepository::parse(repository).map_err(|error| {
457	                CliError::ReleaseArtifactRepositoryInvalid {
458	                    repository: repository.clone(),
459	                    detail: error.to_string(),
460	                }
461	            })?;
462	            // A missing forge-repository is the graph's error; only the match lives here.
463	            if let Some(configured) = workspace
464	                .config
465	                .product_release
466	                .as_ref()
467	                .and_then(|release| release.forge_repository.as_ref())
468	                .filter(|configured| **configured != repository)
469	            {
470	                return Err(CliError::ReleaseForgeRepositoryMismatch {
471	                    configured: configured.as_slug(),
472	                    requested: repository.as_slug(),
473	                });
474	            }
475	            build_release_intent_with_artifacts(
476	                &workspace.root,
477	                &locator,
478	                &runner,
479	                &decision,
480	                ExecutionTrustProfileV1::GitCommit,
481	                callisto_graph::commands::ArtifactBuildPolicy {
482	                    repository,
483	                    workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
484	                    workflow_commit,
485	                },
486	            )?
487	        }
488	        (Some(_), _, _) => {
489	            return Err(CliError::ReleaseOrchestrationFlagsRequired);
490	        }
491	        (None, revision, repository) => {
492	            // The release workflow always passes both flags, including for sources predating [release].
493	            if revision.is_some() || repository.is_some() {
494	                log_line(
495	                    global.format,
496	                    "notice: --orchestration-revision and --artifact-repository ignored: the source has no [release] section; planning with zero artifact slots",
497	                )?;
498	            }
499	            (
500	                build_release_intent(
501	                    &workspace.root,
502	                    &locator,
503	                    &runner,
504	                    &decision,
505	                    ExecutionTrustProfileV1::GitCommit,
506	                )?,
507	                Vec::new(),
508	            )
509	        }
510	    };
511	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
512	        .expect("release plan rejects --dry-run before creating its explicit output");
513	    write_intent(&args.out, &intent, &permit)?;
514	    for diagnostic in &diagnostics {
515	        eprintln!("warning: {}", diagnostic.message);
516	    }
517	    match global.format {
518	        OutputFormat::Json => emit_report(
519	            &mut std::io::stdout(),
520	            &ReleasePlanReport {
521	                intent: intent.clone(),
522	                diagnostics: diagnostics.clone(),
523	            },
524	            global.dry_run,
525	        )?,
526	        OutputFormat::Text => emit_line(&format!(
527	            "Wrote release intent {} to {}",
528	            intent.digest(),
529	            args.out.display()
530	        ))?,
531	    }
532	    Ok(ExitCode::SUCCESS)
533	}
534	
535	fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
536	    let value = read_json_file(&args.input)?;
537	    match global.format {
538	        OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
539	        OutputFormat::Text => emit_line(&serde_json::to_string_pretty(&value).expect("JSON value serializes"))?,
540	    }
541	    Ok(ExitCode::SUCCESS)
542	}
543	
544	fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
545	    // Inputs and the receipt destination are checked before the first effect; a provider failure
546	    // mid-run still leaves landed effects without a receipt, and a rerun adopts them.
547	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleaseExecuteDryRun)?;
548	    let intent = read_intent(&args.intent)?;
549	    let orchestration_revision = callisto_model::CommitSha::parse(&args.orchestration_revision).map_err(|error| {
550	        CliError::ReleaseOrchestrationRevisionInvalid {
551	            revision: args.orchestration_revision.clone(),
552	            detail: error.to_string(),
553	        }
554	    })?;
555	    callisto_model::atomic::probe_atomic_write(&args.receipt, &permit).map_err(|source| CliError::Io {
556	        source,
557	        path: Some(args.receipt.clone()),
558	    })?;
559	    let manifest = args
560	        .artifact_manifest
561	        .as_deref()
562	        .map(read_artifact_manifest)
563	        .transpose()?;
564	    let sealed_python = manifest
565	        .as_ref()
566	        .is_some_and(|manifest| !manifest.distributions.is_empty());
567	    let verified_artifacts = match (
568	        intent.artifact_slots.is_empty(),
569	        manifest.as_ref(),
570	        args.artifact_dir.as_deref(),
571	    ) {
572	        (true, None, None) => None,
573	        (false, Some(manifest), Some(directory)) | (true, Some(manifest), Some(directory))
574	            if sealed_python || !intent.artifact_slots.is_empty() =>
575	        {
576	            let runner = CliCommandRunner;
577	            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
578	        }
579	        (true, _, _) => {
580	            return Err(CliError::ReleaseUnexpectedArtifactInputs);
581	        }
582	        (false, _, _) => {
583	            return Err(CliError::ReleaseMissingArtifactInputs);
584	        }
585	    };
586	    // The run envelope is minted and cross-checked here, before the first
587	    // effect, and is then the single authority for every fact it carries.
588	    let envelope = ReleaseRunEnvelopeV1::new(
589	        orchestration_revision,
590	        &intent,
591	        verified_artifacts
592	            .as_ref()
593	            .map(|artifacts| artifacts.manifest().digest()),
594	    )
595	    .map_err(|error| CliError::ReleaseEnvelopeInvalid {
596	        detail: error.to_string(),
597	    })?;
598	    let runner = CliCommandRunner;
599	    let source_global = source_global(global, args.source_root.as_deref());
600	    let source_workspace = load_workspace(&source_global, &runner)?;
601	    // A missing forge-repository is the graph's error during intent validation; only the match lives here.
602	    if let Some(configured) = source_workspace
603	        .config
604	        .product_release
605	        .as_ref()
606	        .and_then(|release| release.forge_repository.as_ref())
607	    {
608	        if let Some(slot) = intent
609	            .artifact_slots
610	            .iter()
611	            .find(|slot| slot.attestation_policy.repository != *configured)
612	        {
613	            return Err(CliError::ReleaseForgeRepositoryMismatch {
614	                configured: configured.as_slug(),
615	                requested: slot.attestation_policy.repository.as_slug(),
616	            });
617	        }
618	    }
619	    // The workspace root, resolved exactly as `plan` resolves it. Executing
620	    // from a subdirectory must reach the same root, not the process cwd.
621	    let root = source_workspace.root.clone();
622	    let locator = IgnoreWalkLocator::new(&root);
623	    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
624	    let state = execute_release(&capability, &permit, &envelope, verified_artifacts.as_ref())?;
625	    let receipt =
626	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
627	            detail: error.to_string(),
628	        })?;
629	    write_receipt(&args.receipt, &receipt, &permit)?;
630	    match global.format {
631	        OutputFormat::Json => emit_report(
632	            &mut std::io::stdout(),
633	            &ReleaseExecuteReport {
634	                receipt: receipt.clone(),
635	            },
636	            global.dry_run,
637	        )?,
638	        OutputFormat::Text => emit_line(&format!("Release receipt saved to {}", args.receipt.display()))?,
639	    }
640	    Ok(ExitCode::SUCCESS)
641	}
642	
643	fn source_global(global: &GlobalArgs, source_root: Option<&std::path::Path>) -> GlobalArgs {
644	    let mut source = global.clone();
645	    if let Some(root) = source_root {
646	        source.cwd = root.to_path_buf();
647	    }
648	    source
649	}
650	
651	fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
652	    let value = read_json_file(path)?;
653	    // A stale intent is the expected failure after a schema bump; name it
654	    // before serde reports it as an opaque parse error.
655	    let found = &value["schemaVersion"];
656	    if found != &serde_json::json!(ReleaseIntentV1::SCHEMA_VERSION) {
657	        return Err(CliError::ReleaseIntentSchemaUnsupported {
658	            path: path.to_path_buf(),
659	            found: found.to_string(),
660	            expected: ReleaseIntentV1::SCHEMA_VERSION,
661	        });
662	    }
663	    let wire: ReleaseIntentV1Wire = serde_json::from_value(value).map_err(|error| CliError::ReleaseIntentInvalid {
664	        path: path.display().to_string(),
665	        detail: error.to_string(),
666	    })?;
667	    Ok(ReleaseIntentV1::from_wire(wire)?)
668	}
669	
670	fn read_artifact_manifest(path: &std::path::Path) -> Result<ArtifactManifestV1, CliError> {
671	    serde_json::from_value(read_json_file(path)?).map_err(|error| CliError::ArtifactManifestFileInvalid {
672	        path: path.display().to_string(),
673	        detail: error.to_string(),
674	    })
675	}
676	
677	fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
678	    let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
679	        source,
680	        path: Some(path.to_path_buf()),
681	    })?;
682	    serde_json::from_str(&content).map_err(|error| CliError::ReleaseJsonInvalid {
683	        path: path.display().to_string(),
684	        detail: error.to_string(),
685	    })
686	}
687	
688	fn write_intent(path: &std::path::Path, intent: &ReleaseIntentV1, permit: &ApplyPermit) -> Result<(), CliError> {
689	    let content = serde_json::to_string_pretty(intent).expect("release intent serializes") + "\n";
690	    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
691	        source,
692	        path: Some(path.to_path_buf()),
693	    })?;
694	    Ok(())
695	}
696	
697	fn write_receipt(path: &std::path::Path, receipt: &ReleaseReceiptV1, permit: &ApplyPermit) -> Result<(), CliError> {
698	    let content = serde_json::to_string_pretty(receipt).expect("release receipt serializes") + "\n";
699	    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
700	        source,
701	        path: Some(path.to_path_buf()),
702	    })
703	}
704	
705	#[cfg(test)]
706	mod tests {
707	    /// `--package cargo:pkg` (colon form) must be accepted as an alias of
708	    /// `cargo/pkg` -- `ReleasePackageId::parse` alone rejects `:` for its
709	    /// durable on-disk encoding, but the CLI selector grammar is one grammar
710	    /// everywhere, so this file's own selection parser normalizes first.
711	    #[test]
712	    fn parse_release_selection_accepts_colon_as_an_alias_of_slash() {
713	        let colon = super::parse_release_selection("cargo:pkg").expect("colon form must be accepted");
714	        let slash = super::parse_release_selection("cargo/pkg").expect("slash form must be accepted");
715	        assert_eq!(colon, slash);
716	    }
717	
718	    #[test]
719	    fn parse_release_selection_rejects_a_bare_name() {
720	        let err = super::parse_release_selection("pkg").unwrap_err();
721	        assert!(matches!(err, CliError::ReleasePackageInvalid { .. }));
722	    }
723	
724	    use callisto_model::{
725	        RegistryBindingDigest, RegistryBindingId, ReleaseDecisionEntry, ReleaseDecisionV1, ReleaseInclusionReason,
726	        ReleaseInputSnapshotV1, ReleaseOperation, ReleasePackageId, ReleasePackageInputV1, SemanticInputDigest,
727	        SourceIdentity, Version, VersionGrammar,
728	    };
729	    use miette::Diagnostic as _;
730	
731	    use super::*;
732	
733	    fn sample() -> ReleaseIntentV1 {
734	        let package = ReleasePackageId::new(callisto_model::Ecosystem::Cargo, "demo").unwrap();
735	        let version = Version::parse("1.0.0", VersionGrammar::SemVer).unwrap();
736	        let binding =
737	            RegistryBindingId::new("cratesIo", RegistryBindingDigest::parse(&"a".repeat(64)).unwrap()).unwrap();
738	        let publish = ReleaseOperation::registry_publish(package.clone(), version.clone(), binding, vec![]).unwrap();
739	        let tag = ReleaseOperation::tag(package.clone(), version.clone(), vec![publish.id().clone()]).unwrap();
740	        let release =
741	            ReleaseOperation::forge_release(package.clone(), version.clone(), vec![tag.id().clone()]).unwrap();
742	        let published =
743	            ReleaseOperation::forge_publish(package.clone(), version.clone(), vec![release.id().clone()]).unwrap();
744	        let operations = vec![publish, tag, release, published];
745	        let decision = ReleaseDecisionV1::new(vec![ReleaseDecisionEntry {
746	            package: package.clone(),
747	            target_version: version,
748	            reasons: vec![ReleaseInclusionReason::UnreleasedVersion],
749	        }])
750	        .unwrap();
751	        let snapshot = ReleaseInputSnapshotV1::new(
752	            SourceIdentity::GitCommit {
753	                sha: callisto_model::CommitSha::parse(&"b".repeat(40)).unwrap(),
754	            },
755	            vec![ReleasePackageInputV1 {
756	                package,
757	                fingerprint: SemanticInputDigest::parse(&"c".repeat(64)).unwrap(),
758	            }],
759	        )
760	        .unwrap();
761	        ReleaseIntentV1::new(
762	            decision,
763	            snapshot,
764	            ExecutionTrustProfileV1::GitCommit,
765	            operations,
766	            vec![],
767	        )
768	        .unwrap()
769	    }
770	
771	    /// A persisted intent file whose operations were hand-edited into an invalid DAG
772	    /// (here, a duplicate operation id) must surface the domain-specific `ReleaseIntentError`
773	    /// code, not the generic `E236` a `serde` string error would report.
774	    #[test]
775	    fn read_intent_preserves_the_typed_release_intent_error_code() {
776	        let mut value = serde_json::to_value(sample()).expect("intent serializes");
777	        let operations = value["operations"].as_array().expect("operations array").clone();
778	        let duplicate = operations[0].clone();
779	        value["operations"]
780	            .as_array_mut()
781	            .expect("operations array")
782	            .push(duplicate);
783	
784	        let dir = tempfile::tempdir().expect("tempdir");
785	        let path = dir.path().join("intent.json");
786	        std::fs::write(&path, serde_json::to_string(&value).expect("json")).expect("write intent");
787	
788	        let err = read_intent(&path).expect_err("duplicate operation must be rejected");
789	        assert!(
790	            matches!(
791	                err,
792	                CliError::ReleaseIntent(callisto_model::ReleaseIntentError::DuplicateOperation { .. })
793	            ),
794	            "{err:?}"
795	        );
796	        assert_eq!(err.code().map(|c| c.to_string()), Some("E290".to_string()));
797	    }
798	
799	    #[test]
800	    fn plan_text_lists_each_package_version_and_operation() {
801	        let intent = sample();
802	        let text = render_release_plan(&intent, false);
803	        assert!(text.starts_with("Release plan:\n"), "{text}");
804	        for entry in &intent.decision.entries {
805	            assert!(
806	                text.contains(&format!("  {} {}\n", entry.package, entry.target_version)),
807	                "{text}"
808	            );
809	        }
810	        assert_eq!(text.matches("    - ").count(), intent.operations.len(), "{text}");
811	    }
812	
813	    /// A registry publish step names the registry's display name
814	    /// (`crates.io`), not its internal wire key (`cratesIo`).
815	    #[test]
816	    fn plan_text_names_registries_by_display_name_not_wire_key() {
817	        let intent = sample();
818	        let text = render_release_plan(&intent, false);
819	        assert!(text.contains("publish to crates.io"), "{text}");
820	        assert!(!text.contains("cratesIo"), "{text}");
821	    }
822	
823	    /// `use_color: true` renders the release plan as a box-drawing table.
824	    #[test]
825	    fn plan_text_with_color_renders_box_drawing_table() {
826	        let intent = sample();
827	        let text = render_release_plan(&intent, true);
828	        assert!(text.starts_with("Release plan:\n"), "{text}");
829	        assert!(text.contains('\u{2502}'), "expected a box-drawing char in:\n{text}");
830	        for entry in &intent.decision.entries {
831	            assert!(text.contains(&entry.package.to_string()), "{text}");
832	        }
833	    }
834	
835	    /// `use_color: false` never emits box-drawing characters.
836	    #[test]
